using System;using System.Drawing;using System.Reflection;using System.Windows.Forms;
class HeroLoadoutChecks{
 static void Check(bool b,string message){if(!b)throw new Exception(message);}
 [STAThread]static void Main(){try{Application.EnableVisualStyles();using(var game=new Game())using(var view=new HeroLoadoutView()){var flags=BindingFlags.Instance|BindingFlags.NonPublic;view.SaveData=new Save();view.Editable=true;view.SkillArt=(h,s)=>(Image)typeof(Game).GetMethod("HeroSkillImage",flags).Invoke(game,new object[]{h,s});view.Portrait=h=>(Image)typeof(Game).GetMethod("BattleCharacter",flags).Invoke(game,new object[]{h=="aelia"?"hero-female":"hero-male"});view.Size=new Size(1040,690);view.Initialize();Check(view.Complete,"both initial loadouts complete");view.Choose("counter");view.Toggle();Check(view.Loadouts["aelia"].Count==5,"cannot equip sixth");view.Choose("slash");view.Toggle();Check(!view.Complete,"incomplete blocks saving");view.Choose("counter");view.Toggle();Check(view.Complete&&view.Loadouts["aelia"].Contains("counter"),"replacement works");view.Choose("slash");using(var image=new Bitmap(1040,690)){view.DrawToBitmap(image,view.ClientRectangle);image.Save("D:/WORK/Cet6Story/.validation/hero-loadout-redesign.png");}view.SwitchHero();Check(view.Hero=="luchuan"&&view.Loadouts["aelia"].Contains("counter"),"switch keeps draft");view.Editable=false;view.Choose("bolt");view.Toggle();Check(view.Complete&&view.Loadouts["luchuan"].Contains("bolt"),"read-only cannot change");view.Size=new Size(780,520);using(var image=new Bitmap(780,520)){view.DrawToBitmap(image,view.ClientRectangle);image.Save("D:/WORK/Cet6Story/.validation/hero-loadout-small.png");}Console.WriteLine("PASS capacity, replacement, two-character draft, incomplete guard, read-only and responsive rendering");}}catch(Exception e){Console.WriteLine(e.Message);Environment.Exit(1);}}
}
